Vec3 Rotate(Vec3 v,float angle){float sine=std::sin(angle),cosine=std::cos(angle);return {v.X*cosine+v.Z*sine,v.Y,-v.X*sine+v.Z*cosine};}
Vec4 Tint(Vec4 v,Vec4 t){return {v.X*t.X,v.Y*t.Y,v.Z*t.Z,v.W*t.W};}
